// =====================================================
// DONACION - CLIENT SCRIPT
// =====================================================


//-------------------------------------------------------
// Calcula el Total
//-------------------------------------------------------

function calcular_total(frm) {

    let total = 0;

    (frm.doc.conceptos_de_donacion || []).forEach(fila => {
        total += flt(fila.valor);
    });

    frm.set_value("total", total);

}


//-------------------------------------------------------
// Actualizar estado visual del Subconcepto en una fila
//-------------------------------------------------------

function actualizar_estado_subconcepto(frm, cdt, cdn, requiere) {

    let row = frm.fields_dict.conceptos_de_donacion.grid.get_row(cdn);

    if (!row) return;

    row.toggle_editable("subconcepto", requiere);

    if (!requiere) {
        frappe.model.set_value(cdt, cdn, "subconcepto", "");
    }

    row.refresh();

}




//-------------------------------------------------------
// Configurar filtro Subconcepto
//-------------------------------------------------------

function configurar_filtro_subconcepto(frm) {

    frm.set_query(
        "subconcepto",
        "conceptos_de_donacion",
        function (doc, cdt, cdn) {

            let row = locals[cdt][cdn];

            return {
                filters: {
                    concepto: row.concepto,
                    activo: 1
                }
            };

        }
    );

}



//-------------------------------------------------------
// Actualizar comportamiento del Subconcepto
//-------------------------------------------------------

function actualizar_subconcepto(frm, cdt, cdn) {

    let row = locals[cdt][cdn];

    if (!row.concepto)
        return;

    frappe.db.get_value(
        "Concepto",
        row.concepto,
        "requiere_subconcepto"
    ).then(async r => {

        let requiere = cint(r.message.requiere_subconcepto);

        actualizar_estado_subconcepto(
            frm,
            cdt,
            cdn,
            requiere
        );

        //---------------------------------------------------
        // Validar duplicados cuando NO requiere subconcepto
        //---------------------------------------------------

        if (!requiere) {

            let existe = false;

            (frm.doc.conceptos_de_donacion || []).forEach(fila => {

                if (
                    fila.name !== row.name &&
                    fila.concepto === row.concepto
                ) {
                    existe = true;
                }

            });

            if (existe) {

                frappe.msgprint({
                    title: "Concepto repetido",
                    indicator: "orange",
                    message:
                        `El concepto <b>${row.concepto}</b> ya fue agregado.`
                });

                frappe.model.set_value(
                    cdt,
                    cdn,
                    "concepto",
                    ""
                );

                return;
            }

        }

        //---------------------------------------------------
        // Verificar si existen subconceptos
        //---------------------------------------------------

        if (requiere) {

            let cantidad = await frappe.db.count("Subconcepto", {
                filters: {
                    concepto: row.concepto,
                    activo: 1
                }
            });

            if (!cantidad) {

                frappe.msgprint({
                    title: "Configuración",
                    indicator: "orange",
                    message:
                        `El concepto <b>${row.concepto}</b> requiere subconceptos pero aún no tiene ninguno configurado.`
                });

            }

        }

    });

}



//-------------------------------------------------------
// Validaciones generales
//-------------------------------------------------------

async function validar_donacion(frm) {

    //---------------------------------------------------
    // Eliminar filas vacías
    //---------------------------------------------------

    frm.doc.conceptos_de_donacion =
        (frm.doc.conceptos_de_donacion || [])
            .filter(f => f.concepto);

    let usados = [];
    let total = 0;

    //---------------------------------------------------

    for (let fila of frm.doc.conceptos_de_donacion || []) {

        //-------------------------------------------------
        // Valor
        //-------------------------------------------------

        if (flt(fila.valor) <= 0) {

            frappe.throw(
                `El valor del concepto <b>${fila.concepto}</b> debe ser mayor que cero.`
            );

        }

        total += flt(fila.valor);

        //-------------------------------------------------
        // Obtener configuración del Concepto
        //-------------------------------------------------

        let r = await frappe.db.get_value(
            "Concepto",
            fila.concepto,
            "requiere_subconcepto"
        );

        let requiere = cint(r.message.requiere_subconcepto);

        //-------------------------------------------------
        // Validar Subconcepto
        //-------------------------------------------------

        if (requiere && !fila.subconcepto) {

            frappe.throw(
                `El concepto <b>${fila.concepto}</b> requiere un Subconcepto.`
            );

        }

        //-------------------------------------------------
        // Validar repetidos
        //-------------------------------------------------

        let llave = requiere
            ? fila.concepto + "|" + fila.subconcepto
            : fila.concepto;

        if (usados.includes(llave)) {

            if (requiere) {

                frappe.throw(
                    `El subconcepto <b>${fila.subconcepto}</b> ya fue agregado para el concepto <b>${fila.concepto}</b>.`
                );

            } else {

                frappe.throw(
                    `El concepto <b>${fila.concepto}</b> ya fue agregado.`
                );

            }

        }

        usados.push(llave);

    }

    //---------------------------------------------------
    // Debe existir al menos una línea
    //---------------------------------------------------

    if (!frm.doc.conceptos_de_donacion.length) {

        frappe.throw(
            "Debe ingresar al menos un concepto."
        );

    }

    //---------------------------------------------------
    // Actualizar total
    //---------------------------------------------------

    frm.set_value("total", total);

}



//=======================================================
// EVENTOS DONACION
//=======================================================

frappe.ui.form.on("Donacion", {

    setup(frm) {

        configurar_filtro_subconcepto(frm);

    },

    
    refresh: async function(frm) {

    calcular_total(frm);

    for (let fila of (frm.doc.conceptos_de_donacion || [])) {

        if (!fila.concepto) continue;

        let r = await frappe.db.get_value(
            "Concepto",
            fila.concepto,
            "requiere_subconcepto"
        );

        actualizar_estado_subconcepto(
            frm,
            fila.doctype,
            fila.name,
            cint(r.message.requiere_subconcepto)
        );
    }

},
    

    validate: async function (frm) {

        await validar_donacion(frm);

    }

});



//=======================================================
// EVENTOS TABLA HIJA
//=======================================================

frappe.ui.form.on("Concepto de Donacion", {

    //---------------------------------------------------

    concepto(frm, cdt, cdn) {

        actualizar_subconcepto(frm, cdt, cdn);

    },

    //---------------------------------------------------

    subconcepto(frm, cdt, cdn) {

        let row = locals[cdt][cdn];

        if (!row.concepto || !row.subconcepto)
            return;

        let existe = false;

        (frm.doc.conceptos_de_donacion || []).forEach(fila => {

            if (
                fila.name !== row.name &&
                fila.concepto === row.concepto &&
                fila.subconcepto === row.subconcepto
            ) {

                existe = true;

            }

        });

        if (existe) {

            frappe.msgprint({
                title: "Subconcepto repetido",
                indicator: "orange",
                message:
                    `Ya existe el subconcepto <b>${row.subconcepto}</b> para el concepto <b>${row.concepto}</b>.`
            });

            frappe.model.set_value(
                cdt,
                cdn,
                "subconcepto",
                ""
            );

        }

    },

    //---------------------------------------------------

    valor(frm) {

        calcular_total(frm);

    },

    //---------------------------------------------------

    conceptos_de_donacion_add(frm) {

        calcular_total(frm);

    },

    //---------------------------------------------------

    conceptos_de_donacion_remove(frm) {

        calcular_total(frm);

    }

});

// =====================================================
// REGLA DE DISTRIBUCION
// =====================================================

frappe.ui.form.on("Regla de Distribucion", {

    //--------------------------------------------------
    // Setup
    //--------------------------------------------------

    setup(frm) {

        frm.set_query("subconcepto", function () {

            if (!frm.doc.concepto) {

                return {
                    filters: {
                        name: "__none"
                    }
                };

            }

            return {
                filters: {
                    concepto: frm.doc.concepto,
                    activo: 1
                }
            };

        });

    },

    //--------------------------------------------------
    // Al cambiar Concepto
    //--------------------------------------------------

    concepto(frm) {

        frm.set_value("subconcepto", "");

    },

    //--------------------------------------------------
    // Validaciones
    //--------------------------------------------------

    async validate(frm) {

        //--------------------------------------------------
        // Validar Subconcepto
        //--------------------------------------------------

        if (frm.doc.subconcepto) {

            let r = await frappe.db.get_value(
                "Subconcepto",
                frm.doc.subconcepto,
                "concepto"
            );

            if (r.message.concepto != frm.doc.concepto) {

                frappe.throw(
                    "El subconcepto seleccionado no pertenece al Concepto."
                );

            }

        }

        //--------------------------------------------------
        // Debe existir al menos un destino
        //--------------------------------------------------

        if (!frm.doc.destinos || !frm.doc.destinos.length) {

            frappe.throw(
                "Debe configurar al menos un destino de distribución."
            );

        }

        //--------------------------------------------------
        // Validaciones de Destinos
        //--------------------------------------------------

        let total = 0;
        let usados = [];

        (frm.doc.destinos || []).forEach(fila => {

            //--------------------------------------
            // Tipo Destino
            //--------------------------------------

            if (!fila.tipo_destino) {

                frappe.throw(
                    "Existe una fila sin Tipo Destino."
                );

            }

            //--------------------------------------
            // Porcentaje
            //--------------------------------------

            if (flt(fila.porcentaje) <= 0) {

                frappe.throw(
                    `El porcentaje del destino "${fila.tipo_destino}" debe ser mayor que cero.`
                );

            }

            total += flt(fila.porcentaje);

            //--------------------------------------
            // Destino repetido
            //--------------------------------------

            if (usados.includes(fila.tipo_destino)) {

                frappe.throw(
                    `El Tipo Destino "${fila.tipo_destino}" está repetido.`
                );

            }

            usados.push(fila.tipo_destino);

        });

        //--------------------------------------------------
        // Total = 100
        //--------------------------------------------------

        if (Math.abs(total - 100) > 0.0001) {

            frappe.throw(
                `La suma de los porcentajes debe ser exactamente 100%. Actualmente es ${total}%.`
            );

        }

    }

});

// ======================================================
// DONACION
// ======================================================


//--------------------------------------------------------
// Calcula la distribución
//--------------------------------------------------------

function calcular_distribucion(frm) {

    frappe.call({

        method:
            "ifi_portal.api.distribucion.calcular_distribucion",

        args: {

            docname: frm.doc.name

        },

        freeze: true,

        freeze_message:
            __("Calculando distribución..."),

        callback: function (r) {

            if (!r.message)
                return;

            //------------------------------------------------
            // Limpiar distribución anterior
            //------------------------------------------------

            frm.clear_table("distribuciones");

            //------------------------------------------------
            // Agregar nuevas filas
            //------------------------------------------------

            r.message.forEach(function (fila) {

                let d = frm.add_child("distribuciones");

                d.concepto = fila.concepto;

                d.subconcepto = fila.subconcepto;

                d.tipo_destino = fila.tipo_destino;

                d.porcentaje = fila.porcentaje;

                d.valor = fila.valor;

            });

            //------------------------------------------------

            frm.refresh_field("distribuciones");

            frappe.show_alert({

                message: __("Distribución calculada correctamente."),

                indicator: "green"

            });

        }

    });

}



//========================================================
// DONACION
//========================================================

frappe.ui.form.on("Donacion", {

    //----------------------------------------------------

    refresh(frm) {

        //------------------------------------------------
        // Botón
        //------------------------------------------------

        if (!frm.is_new()) {

            frm.add_custom_button(

                __("Calcular Distribución"),

                function () {

                    calcular_distribucion(frm);

                },

                __("Nehemías")

            );

        }

    }

});

frappe.ui.form.on("Donacion", {
    setup(frm) {
        frm.set_query("unidad_organizacional", function () {
            return {
                query: "ifi_portal.security.api.link_query"
            };
        });
    }
});

frappe.ui.form.on("Donacion", {
    refresh(frm) {
        toggle_banco(frm);
    },

    forma_de_pago(frm) {
        toggle_banco(frm);
    }
});

function toggle_banco(frm) {
    frm.toggle_display(
        "banco_recaudo", // o cuenta_recaudo, según el fieldname real
        ["Transferencia", "PSE", "Wompi"].includes(frm.doc.forma_de_pago)
    );
}

frappe.ui.form.on("Planilla", {

    setup(frm) {

        // Seguridad de Unidad Organizacional
        frm.set_query("unidad_organizacional", function () {
            return {
                query: "ifi_portal.security.api.link_query"
            };
        });

        // Donaciones disponibles
        frm.set_query("donacion", "donaciones", function () {

            const usadas = (frm.doc.donaciones || [])
                .map(d => d.donacion)
                .filter(Boolean);

            return {
                query: "ifi_portal.security.api.donacion_query",
                filters: {
                    unidad_organizacional: frm.doc.unidad_organizacional,
                    calendario: frm.doc.calendario,
                    entrega: frm.doc.entrega,
                    planilla: frm.doc.name || "",
                    usadas: usadas
                }
            };
        });

    }

});

frappe.ui.form.on("Planilla", {

    refresh(frm) {

        toggle_tipo_planilla(frm);
        actualizar_total_planilla(frm);

        cargar_cuentas_consignacion(frm);
    },

    unidad_organizacional(frm) {

        frm.set_value("cuenta_consignacion", "");

        cargar_cuentas_consignacion(frm);
    }

});


function cargar_cuentas_consignacion(frm) {

    if (!frm.doc.unidad_organizacional) {
        return;
    }

    frappe.call({
        method: "filtrar_cuenta_consignacion_planilla",
        args: {
            unidad_organizacional: frm.doc.unidad_organizacional
        },
        callback(r) {

            const bancos = r.message || [];

            frm.set_query("cuenta_consignacion", function () {
                return {
                    filters: {
                        name: ["in", bancos]
                    }
                };
            });

            frm.refresh_field("cuenta_consignacion");
        }
    });

}

frappe.ui.form.on("Planilla Donacion", {

    donacion(frm, cdt, cdn) {

        let row = locals[cdt][cdn];

        let repetido = false;

        (frm.doc.donaciones || []).forEach(fila => {

            if (
                fila.name !== row.name &&
                fila.donacion === row.donacion
            ) {
                repetido = true;
            }

        });

        if (repetido) {

            frappe.msgprint({
                title: "Donación repetida",
                indicator: "red",
                message: `La donación <b>${row.donacion}</b> ya fue agregada a la planilla.`
            });

            frappe.model.set_value(
                cdt,
                cdn,
                "donacion",
                ""
            );
        }

    }

});

frappe.ui.form.on("Planilla", {

    validate(frm) {

        // Eliminar donaciones vacías
        frm.doc.donaciones = (frm.doc.donaciones || []).filter(row => {
            return !!row.donacion;
        });

        // Eliminar consignaciones con valor 0
        frm.doc.consignaciones = (frm.doc.consignaciones || []).filter(row => {
            return flt(row.valor_consignado) > 0;
        });

        frm.refresh_field("donaciones");
        frm.refresh_field("consignaciones");
    }

});

frappe.ui.form.on("Planilla", {

    cuenta_consignacion(frm) {

        if (
            frm.is_new() &&
            frm.doc.unidad_organizacional &&
            frm.doc.cuenta_consignacion &&
            frm.doc.fecha
        ) {

            frm.save();

        }

    }

});
